// Bad: Recalculates every time
function expensiveSum(arr) {
  return arr.reduce((a, b) => a + b, 0);
}
console.log(expensiveSum([1, 2, 3])); // recalculated
console.log(expensiveSum([1, 2, 3])); // recalculated again

// Good: Cache the result
let cachedResult = null;
function efficientSum(arr) {
  if (!cachedResult) cachedResult = arr.reduce((a, b) => a + b, 0);
  return cachedResult;
}
console.log(efficientSum([1, 2, 3])); // calculated once
console.log(efficientSum([1, 2, 3])); // uses cache
